<?php
	/*	
	*	Fundraise Master Plugin
	*	---------------------------------------------------------------------
	*	for cause post type
	*	---------------------------------------------------------------------
	*/

	// create post type
	add_action('init', 'frmaster_cause_init');
	if( !function_exists('frmaster_cause_init') ){
		function frmaster_cause_init(){
			
			// custom post type
			$slug = apply_filters('frmaster_custom_post_slug', 'cause', 'cause');
			$supports = apply_filters('frmaster_custom_post_support', array('title', 'editor', 'author', 'thumbnail', 'comments', 'excerpt', 'custom-fields', 'revisions'), 'cause');

			$labels = array(
				'name'               => esc_html__('Cause', 'frmaster'),
				'singular_name'      => esc_html__('Cause', 'frmaster'),
				'menu_name'          => esc_html__('Cause', 'frmaster'),
				'name_admin_bar'     => esc_html__('Cause', 'frmaster'),
				'add_new'            => esc_html__('Add New', 'frmaster'),
				'add_new_item'       => esc_html__('Add New Cause', 'frmaster'),
				'new_item'           => esc_html__('New Cause', 'frmaster'),
				'edit_item'          => esc_html__('Edit Cause', 'frmaster'),
				'view_item'          => esc_html__('View Cause', 'frmaster'),
				'all_items'          => esc_html__('All Cause', 'frmaster'),
				'search_items'       => esc_html__('Search Cause', 'frmaster'),
				'parent_item_colon'  => esc_html__('Parent Cause:', 'frmaster'),
				'not_found'          => esc_html__('No cause found.', 'frmaster'),
				'not_found_in_trash' => esc_html__('No cause found in Trash.', 'frmaster')
			);
			$args = array(
				'labels'             => $labels,
				'description'        => esc_html__('Description.', 'frmaster'),
				'public'             => true,
				'publicly_queryable' => true,
				'exclude_from_search'=> false,
				'show_ui'            => true,
				'show_in_menu'       => true,
				'query_var'          => true,
				'rewrite'            => array('slug' => $slug),
				'map_meta_cap' 		 => true,
				'capabilities' => array(
					'edit_post'          => 'edit_cause', 
					'read_post'          => 'read_cause', 
					'delete_post'        => 'delete_cause', 
					'delete_posts'       => 'delete_causes', 
					'edit_posts'         => 'edit_causes', 
					'create_posts'       => 'edit_causes', 
					'edit_others_posts'  	=> 'edit_others_causes', 
					'delete_others_posts '  => 'edit_others_causes', 
					'publish_posts'      	=> 'publish_causes',       
					'edit_published_posts' 	=> 'publish_causes',       
					'read_private_posts' 	=> 'read_private_causes', 
					'edit_private_posts' 	=> 'read_private_causes', 
					'delete_private_posts' 	=> 'read_private_causes', 
				),
				'has_archive'        => false,
				'hierarchical'       => false,
				'menu_position'      => null,
				'supports'           => $supports
			);
			register_post_type('cause', $args);

			// custom taxonomy
			$slug = apply_filters('frmaster_custom_post_slug', 'cause-category', 'cause_category');
			$args = array(
				'hierarchical'      => true,
				'label'             => esc_html__('Cause Category', 'frmaster'),
				'show_ui'           => true,
				'show_admin_column' => true,
				'query_var'         => true,
				'rewrite'           => array('slug' => $slug),
				'capabilities'		=> array(
					'manage_terms' => 'manage_cause_category', 
					'edit_terms' => 'manage_cause_category', 
					'delete_terms' => 'manage_cause_category', 
					'assign_terms' => 'manage_cause_category'
				)
			);
			register_taxonomy('cause_category', array('cause'), $args);
			register_taxonomy_for_object_type('cause_category', 'cause');

			$slug = apply_filters('frmaster_custom_post_slug', 'cause-tag', 'cause_tag');
			$args = array(
				'hierarchical'      => false,
				'label'             => esc_html__('Cause Tag', 'frmaster'),
				'show_ui'           => true,
				'show_admin_column' => true,
				'query_var'         => true,
				'rewrite'           => array('slug' => $slug),
				'capabilities'		=> array(
					'manage_terms' => 'manage_cause_tag', 
					'edit_terms' => 'manage_cause_tag', 
					'delete_terms' => 'manage_cause_tag', 
					'assign_terms' => 'manage_cause_tag'
				)
			);
			register_taxonomy('cause_tag', array('cause'), $args);
			register_taxonomy_for_object_type('cause_tag', 'cause');

			// apply single template filter
			add_filter('single_template', 'frmaster_cause_template');

		}
	} // frmaster_post_type_init

	if( !function_exists('frmaster_cause_template') ){
		function frmaster_cause_template( $template ){

			if( get_post_type() == 'cause' ){
				$template = FRMASTER_LOCAL . '/single/cause.php';
			}

			return $template;
		}
	}

	// add page builder to cause
	if( is_admin() ){ add_filter('gdlr_core_page_builder_post_type', 'frmaster_gdlr_core_cause_add_page_builder'); }
	if( !function_exists('frmaster_gdlr_core_cause_add_page_builder') ){
		function frmaster_gdlr_core_cause_add_page_builder( $post_type ){
			$post_type[] = 'cause';
			return $post_type;
		}
	}	

	// init page builder value
	if( is_admin() ){ add_filter('gdlr_core_cause_page_builder_val_init', 'frmaster_cause_page_builder_val_init'); }
