	if( !function_exists('frmaster_increase_donation_amount') ){
		function frmaster_increase_donation_amount($cause_id, $amount, $increase_donor = true){
			$donor_amount = get_post_meta($cause_id, 'frmaster-donor-amount', true);
			$donated_amount = get_post_meta($cause_id, 'frmaster-donated-amount', true);

			if( is_numeric($amount) ){
				if( $increase_donor ){
					$donor_amount++;
					update_post_meta($cause_id, 'frmaster-donor-amount', $donor_amount);
				}

				$donated_amount = floatval($donated_amount) + floatval($amount);
				update_post_meta($cause_id, 'frmaster-donated-amount', $donated_amount);
			}
		}
	}

	if( !function_exists('frmaster_get_follow_link') ){
		function frmaster_get_follow_link( $text = '', $link_class = 'frmaster-button frmaster-border-style' ){

			$logged_in = is_user_logged_in();

			$ret = '';
			if( !$logged_in ){
				$ret .= frmaster_lightbox_content(array(
					'id' => 'follow-login',
					'title' => esc_html__('Login', 'frmaster'),
					'content' => frmaster_get_login_form(false)
				));
				$ret .= '<a href="#" class="frmaster-follow ' . esc_attr($link_class) . '" data-frmlb="follow-login" >';
			}else{
				global $current_user;
				$follow_ids = get_user_meta($current_user->ID, 'frmaster-follow', true);
				$follow_ids = empty($follow_ids)? array(): $follow_ids;
				$follow_active = in_array(get_the_ID(), $follow_ids);

				if( $follow_active ){
					$ret .= '<a class="frmaster-follow ' . esc_attr($link_class) . ' frmaster-active" >';
				}else{
					$ret .= '<a href="#" class="frmaster-follow ' . esc_attr($link_class) . '" ';
					$ret .= ' data-ajax-url="' . esc_url(FRMASTER_AJAX_URL) . '" ';
					$ret .= ' data-cause-id="' . esc_attr(get_the_ID()) . '" >';
				}
			}
			if( empty($text) ){
				$ret .= '<i class="fa fa-heart-o" ></i>' . esc_html__('Follow', 'frmaster');
			}else{
				$ret .= frmaster_text_filter($text);
			}
			$ret .= '</a>';

			return $ret;
		}
	}

	if( !function_exists('frmaster_get_cause_social') ){
		function frmaster_get_cause_social($post_meta = array()){

			$url = get_permalink();
			$title = urlencode(html_entity_decode(get_the_title(), ENT_COMPAT, 'UTF-8'));

			$ret = '';

			if( !empty($post_meta['social-facebook']) && $post_meta['social-facebook'] == 'enable' ){
				$share_url = 'https://www.facebook.com/sharer/sharer.php?caption=' . $title . '&u=' . $url;
				$onclick_event = 'javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=602,width=555\');return false;';

				$ret .= '<a class="gdlr-core-social-share-facebook" href="' . esc_url($share_url) . '" target="_blank" onclick="' . esc_attr($onclick_event) . '" ><i class="fa fa-facebook" ></i></a>';
			}

			if( !empty($post_meta['social-linkedin']) && $post_meta['social-linkedin'] == 'enable' ){
				$share_url = 'http://www.linkedin.com/shareArticle?mini=true&url=' . $url . '&title=' . $title;
				$onclick_event = 'javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=452,width=550\');return false;';

				$ret .= '<a class="gdlr-core-social-share-linkedin" href="' . esc_url($share_url) . '" target="_blank" onclick="' . esc_attr($onclick_event) . '" ><i class="fa fa-linkedin" ></i></a>';
			}

			if( !empty($post_meta['social-pinterest']) && $post_meta['social-pinterest'] == 'enable' ){
				$share_url = 'http://pinterest.com/pin/create/button/?url=' . $url;
				if( has_post_thumbnail() ){
					$share_url .= '&media=' . wp_get_attachment_url(get_post_thumbnail_id(), 'large');
				}
				$onclick_event = 'javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=553,width=750\');return false;';

				$ret .= '<a class="gdlr-core-social-share-pinterest" href="' . esc_url($share_url) . '" target="_blank" onclick="' . esc_attr($onclick_event) . '" ><i class="fa fa-pinterest-p" ></i></a>';
			}

			if( !empty($post_meta['social-stumbleupon']) && $post_meta['social-stumbleupon'] == 'enable' ){
				$share_url = 'http://www.stumbleupon.com/submit?url=' . $url . '&title=' . $title;
				$onclick_event = 'javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=553,width=750\');return false;';

				$ret .= '<a class="gdlr-core-social-share-stumbleupon" href="' . esc_url($share_url) . '" target="_blank" onclick="' . esc_attr($onclick_event) . '" ><i class="fa fa-stumbleupon" ></i></a>';
			}

			if( !empty($post_meta['social-twitter']) && $post_meta['social-twitter'] == 'enable' ){
				$share_url = 'https://twitter.com/intent/tweet?text=' . $title . '&url=' . $url;
				$onclick_event = 'javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=255,width=555\');return false;';

				$ret .= '<a class="gdlr-core-social-share-twitter" href="' . esc_url($share_url) . '" target="_blank" onclick="' . esc_attr($onclick_event) . '" ><i class="fa fa-twitter" ></i></a>';
			}

			if( !empty($post_meta['social-email']) && $post_meta['social-email'] == 'enable' ){
				$mail_title = esc_html__('Site sharing', 'goodlayers-core');
				$mail_body = esc_html__('Please check this site out', 'goodlayers-core');
				$share_url = "mailto:?subject={$mail_title}&amp;body={$mail_body} {$url}";

				$ret .= '<a class="gdlr-core-social-share-email" href="' . esc_url($share_url) . '" ><i class="fa fa-envelope" ></i></a>';
			}

			if( !empty($ret) ){
				$ret  = '<div class="frmaster-cause-social-share-wrap" >' . $ret . '</div>';
			}

			return $ret;

		} // frmaster_get_cause_social
	}